switch (order.status) {
  case 'CART':
  case 'PAYMENT_FAILED':
    // 課金されていないことが確定している
    order.status = 'CANCELLED';
    break;
  case 'PAID': { /* 変更なし */ }
  default:
    // PENDING_PAYMENT は課金されたか分からない。
    // 照合バッチが PAID か PAYMENT_FAILED に決めてから取り消してもらう
    throw new InvalidOrderStateError(order, 'cancelled');
}

const raw = env.CANCELLATION_FEE_PERCENT;
const feePercent = raw === undefined || raw === '' ? 10 : Number(raw);
if (!Number.isFinite(feePercent) || feePercent < 0 || feePercent > 100) {
  throw new Error(`CANCELLATION_FEE_PERCENT must be 0-100: ${raw}`);
}
